class Solution {
public:
    int waysToPartition(vector<int>& nums, int k) {
        int n = nums.size();
        vector<long long> prefix(n);
        prefix[0] = nums[0];
        for (int i = 1; i < n; i++) prefix[i] = prefix[i-1] + nums[i];
        long long total = prefix[n-1];

        unordered_map<long long, int> leftCount, rightCount;
        for (int p = 1; p < n; p++) {
            rightCount[2 * prefix[p-1]]++;
        }

        int ans = rightCount[total];

        for (int i = 0; i < n; i++) {
            if (i >= 1) {
                long long v = 2 * prefix[i-1];
                rightCount[v]--;
                leftCount[v]++;
            }
            long long delta = (long long)k - nums[i];
            int ways = leftCount[total + delta] + rightCount[total - delta];
            if (ways > ans) ans = ways;
        }

        return ans;
    }
};
